#include <stdio.h>

void call_counter(void) {
    static int calls = 0;   // initialized once, persists across calls
    calls++;
    printf("Called %d time(s)\n", calls);
}

int main(void) {
    call_counter();   // Called 1 time(s)
    call_counter();   // Called 2 time(s)
    call_counter();   // Called 3 time(s)
    return 0;
}
